;(function () {
  const pick = (v) => (v && /^it/i.test(v) ? 'it' : v && /^en/i.test(v) ? 'en' : null)
  const browser = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language]).map(pick).find(Boolean)
  window.WA_LANG = browser || 'en'
  // the language is automatic: drop any choice saved by older versions
  try { localStorage.removeItem('wa_lang') } catch { /* ignore */ }
  if (/(^|;\s*)wa_lang=/.test(document.cookie)) document.cookie = 'wa_lang=;path=/;max-age=0;samesite=lax'
  window.t = function (key, ...params) {
    const d = window.WA_I18N[window.WA_LANG] || window.WA_I18N.en
    const s = d[key] ?? window.WA_I18N.en[key] ?? key
    return s.replace(/\{(\d+)\}/g, (m, i) => (params[i] !== undefined ? String(params[i]) : m))
  }
  window.applyI18n = function (root) {
    const r = root || document
    document.documentElement.lang = window.WA_LANG
    r.querySelectorAll('[data-i18n]').forEach((el) => { el.textContent = window.t(el.dataset.i18n) })
    r.querySelectorAll('[data-i18n-html]').forEach((el) => { el.innerHTML = window.t(el.dataset.i18nHtml) })
    r.querySelectorAll('[data-i18n-ph]').forEach((el) => { el.placeholder = window.t(el.dataset.i18nPh) })
  }
})()

